// middleware.ts — generated by HDD for a Vercel/Next.js origin.
// Refuses any request that did not arrive through the HDD proxy with the shared secret header.
// LIMITATION: the edge runtime has no constant-time string comparison available; the check
// below is a plain equality test. Use a long random secret (32+ bytes) and rotate it if leaked.
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

const SECRET = process.env.HDD_ORIGIN_SECRET ?? "";
const HEADER = "X-HDD-Origin-Secret";

export function middleware(request: NextRequest): NextResponse {
  const supplied = request.headers.get(HEADER) ?? "";
  if (SECRET.length === 0 || supplied !== SECRET) {
    return new NextResponse("Forbidden", { status: 403 });
  }
  return NextResponse.next();
}

export const config = { matcher: "/:path*" };

// middleware.ts (Edge Middleware alternative, no vercel.json needed) — generated by HDD.
// Vercel runs middleware.ts at the edge; pinning the runtime and matcher keeps static assets
// out of the check. The constant-time limitation of the edge runtime still applies.
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

const SECRET = process.env.HDD_ORIGIN_SECRET ?? "";

export function middleware(request: NextRequest): NextResponse {
  const supplied = request.headers.get("X-HDD-Origin-Secret") ?? "";
  if (SECRET.length === 0 || supplied !== SECRET) {
    return new NextResponse("Forbidden", { status: 403 });
  }
  return NextResponse.next();
}

export const config = {
  runtime: "edge",
  matcher: "/((?!_next/static|favicon.ico).*)",
};
